import { PageHeader } from '@gntik-ai/blocks';
import { Keyboard } from '@gntik-ai/icons';
import {
  Button,
  Dialog,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  Page,
  type BreadcrumbItem,
} from '@gntik-ai/ui';
import type { ReactElement } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import { shortcutBreadcrumbs, shortcutGroups, type ShortcutGroup } from './data';
import { ShortcutSheet } from './ShortcutSheet';

export interface KeyboardShortcutsProps {
  title: string;
  description: string;
  groups: ShortcutGroup[];
  breadcrumbs: BreadcrumbItem[];
  currentHref: string;
  /** ConsoleShell props (app nav, user, workspaces, sidebar footer, topbar…). */
  shell: Omit<ConsoleShellProps, 'children'>;
}

/** Keyboard shortcuts as a console page: ConsoleShell + Page with a searchable sheet. */
export default function KeyboardShortcutsPage(props: Partial<KeyboardShortcutsProps>) {
  const {
    title = 'Keyboard shortcuts',
    description = 'Move around the console without leaving the keyboard. Press ? anywhere to open this list.',
    groups = shortcutGroups,
    breadcrumbs = shortcutBreadcrumbs,
    currentHref = '/help/shortcuts',
    shell,
  } = props;
  return (
    <ConsoleShell breadcrumbs={breadcrumbs} currentHref={currentHref} {...shell}>
      <Page header={<PageHeader breadcrumbs={null} title={title} description={description} status="" meta={[]} tabs={null} actions={[]} />}>
        <ShortcutSheet groups={groups} />
      </Page>
    </ConsoleShell>
  );
}

export interface KeyboardShortcutsDialogProps {
  groups?: ShortcutGroup[];
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Trigger element (rendered through Base UI `render`); omit for a controlled dialog opened by `?`. */
  trigger?: ReactElement | null;
  title?: string;
}

/** The same sheet in a Dialog, for the `?` shortcut or a help menu item. */
export function KeyboardShortcutsDialog({
  groups = shortcutGroups,
  open,
  defaultOpen,
  onOpenChange,
  trigger = <Button variant="secondary" icon={Keyboard} />,
  title = 'Keyboard shortcuts',
}: KeyboardShortcutsDialogProps) {
  return (
    <Dialog open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange}>
      {trigger && <DialogTrigger render={trigger}>{title}</DialogTrigger>}
      <DialogContent size="lg">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>Search by action or key.</DialogDescription>
        </DialogHeader>
        <DialogBody className="max-h-[70vh] overflow-y-auto">
          <ShortcutSheet groups={groups} headingLevel={3} columns={1} autoFocus />
        </DialogBody>
      </DialogContent>
    </Dialog>
  );
}

import { Keyboard, Search } from '@gntik-ai/icons';
import { EmptyState, Grid, Heading, Input, KbdCombo, Stack, Text } from '@gntik-ai/ui';
import { useId, useState } from 'react';
import { filterShortcuts, type ShortcutGroup } from './data';

export interface ShortcutSheetProps {
  groups: readonly ShortcutGroup[];
  /** Heading level of the group titles (h2 on the page, h3 inside the dialog). */
  headingLevel?: 2 | 3;
  /** Columns of groups at `md` and up. */
  columns?: 1 | 2;
  autoFocus?: boolean;
}

/** Searchable shortcut sheet shared by the page and the dialog. */
export function ShortcutSheet({ groups, headingLevel = 2, columns = 2, autoFocus }: ShortcutSheetProps) {
  const [query, setQuery] = useState('');
  const countId = useId();
  const visible = filterShortcuts(groups, query);
  const total = visible.reduce((n, g) => n + g.shortcuts.length, 0);
  return (
    <Stack gap={5}>
      <Stack gap={2}>
        <Input
          type="search"
          aria-label="Search shortcuts"
          aria-describedby={countId}
          placeholder="Search shortcuts…"
          leadingIcon={Search}
          value={query}
          onValueChange={setQuery}
          autoFocus={autoFocus}
          className="max-w-md"
        />
        <Text id={countId} variant="caption" tone="muted" aria-live="polite">
          {total === 1 ? '1 shortcut' : `${total} shortcuts`}
        </Text>
      </Stack>
      {visible.length === 0 ? (
        <EmptyState icon={Keyboard} size="sm" titleAs={headingLevel === 2 ? 'h2' : 'h3'} title="No shortcuts match" description="Try another word, such as “save” or “go to”." />
      ) : (
        <Grid cols={{ base: 1, md: columns }} gap={6}>
          {visible.map((g) => (
            <section key={g.id} aria-labelledby={`${countId}-${g.id}`}>
              <Heading id={`${countId}-${g.id}`} level={headingLevel} size="xs" className="mb-2">
                {g.title}
              </Heading>
              <ul className="divide-y divide-border rounded-lg border border-border">
                {g.shortcuts.map((s) => (
                  <li key={s.id} className="flex items-center justify-between gap-4 px-3.5 py-2.5">
                    <Text as="span" variant="supporting">
                      {s.description}
                    </Text>
                    <span className="flex shrink-0 items-center gap-1.5">
                      <KbdCombo keys={s.keys} />
                      {s.then && (
                        <>
                          <Text as="span" variant="caption" tone="muted">
                            then
                          </Text>
                          <KbdCombo keys={s.then} />
                        </>
                      )}
                    </span>
                  </li>
                ))}
              </ul>
            </section>
          ))}
        </Grid>
      )}
    </Stack>
  );
}

import type { BreadcrumbItem } from '@gntik-ai/ui';

export interface Shortcut {
  id: string;
  /** What the shortcut does. */
  description: string;
  /** Keys pressed together, e.g. ['⌘', 'K']. */
  keys: string[];
  /** A second combination that does the same (e.g. a sequence "G then P"). */
  then?: string[];
}

export interface ShortcutGroup {
  id: string;
  title: string;
  shortcuts: Shortcut[];
}

export const shortcutBreadcrumbs: BreadcrumbItem[] = [{ label: 'Help', href: '/help' }, { label: 'Keyboard shortcuts' }];

/** Neutral console shortcuts, grouped by area. */
export const shortcutGroups: ShortcutGroup[] = [
  {
    id: 'general',
    title: 'General',
    shortcuts: [
      { id: 'palette', description: 'Open the command palette', keys: ['⌘', 'K'] },
      { id: 'help', description: 'Show keyboard shortcuts', keys: ['?'] },
      { id: 'sidebar', description: 'Collapse or expand the sidebar', keys: ['⌘', 'B'] },
      { id: 'theme', description: 'Switch theme', keys: ['⌘', '⇧', 'L'] },
    ],
  },
  {
    id: 'navigation',
    title: 'Navigation',
    shortcuts: [
      { id: 'go-home', description: 'Go to overview', keys: ['G'], then: ['O'] },
      { id: 'go-projects', description: 'Go to projects', keys: ['G'], then: ['P'] },
      { id: 'go-deployments', description: 'Go to deployments', keys: ['G'], then: ['D'] },
      { id: 'go-settings', description: 'Go to settings', keys: ['G'], then: ['S'] },
    ],
  },
  {
    id: 'lists',
    title: 'Lists and tables',
    shortcuts: [
      { id: 'next', description: 'Next row', keys: ['J'] },
      { id: 'prev', description: 'Previous row', keys: ['K'] },
      { id: 'open', description: 'Open the selected row', keys: ['↵'] },
      { id: 'select', description: 'Select the row', keys: ['X'] },
      { id: 'filter', description: 'Focus the filter', keys: ['/'] },
    ],
  },
  {
    id: 'editing',
    title: 'Editing',
    shortcuts: [
      { id: 'save', description: 'Save changes', keys: ['⌘', 'S'] },
      { id: 'submit', description: 'Submit a form or comment', keys: ['⌘', '↵'] },
      { id: 'cancel', description: 'Cancel and close', keys: ['Esc'] },
      { id: 'undo', description: 'Undo', keys: ['⌘', 'Z'] },
    ],
  },
];

/** Groups with only the shortcuts whose description or keys match the query. */
export function filterShortcuts(groups: readonly ShortcutGroup[], query: string): ShortcutGroup[] {
  const q = query.trim().toLowerCase();
  if (!q) return [...groups];
  return groups
    .map((g) => ({
      ...g,
      shortcuts: g.shortcuts.filter(
        (s) =>
          s.description.toLowerCase().includes(q) ||
          g.title.toLowerCase().includes(q) ||
          [...s.keys, ...(s.then ?? [])].join(' ').toLowerCase() === q,
      ),
    }))
    .filter((g) => g.shortcuts.length > 0);
}

import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import { SidebarLayout, type BreadcrumbItem, type NavGroup, type SidebarLayoutProps, type UserMenuUser, type Workspace } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  return (
    <SidebarLayout
      fullScreen
      storageKey={storageKey}
      sidebarLabel={sidebarLabel}
      collapseMode={collapseMode}
      sidebarHeader={({ collapsed }) => (
        <AppSidebarHeader
          collapsed={collapsed}
          workspaces={workspaces}
          currentWorkspaceId={currentWorkspaceId}
          onWorkspaceChange={onWorkspaceChange}
          onCreateWorkspace={onCreateWorkspace}
        />
      )}
      sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
      sidebarFooter={({ collapsed }) => (
        <AppSidebarFooter
          collapsed={collapsed}
          user={user}
          usage={usage}
          helpHref={helpHref}
          helpLabel={helpLabel}
          userMenuItems={userMenuItems}
          onSignOut={onSignOut}
        />
      )}
      topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
    >
      {children}
    </SidebarLayout>
  );
}
